-- Hosbah: one backup run of a data service. kind is 'manual' (Back up now / MCP backup_now) or
-- 'scheduled'. The agent runs pg_dump -Fc / mysqldump / a Redis RDB save and pushes it into a restic
-- repository on the target; snapshot_id is restic's, size_bytes the dump size. restore_tested_at is
-- set only after a restore into a throwaway container verified the dump restores (restore_status
-- pass/fail); a scheduled restore-test runs after a successful scheduled backup.
ALTER TABLE backups ADD CONSTRAINT backups_kind_check CHECK (kind IN ('manual', 'scheduled'));
ALTER TABLE backups ADD CONSTRAINT backups_status_check CHECK (status IN ('pending', 'running', 'succeeded', 'failed'));
ALTER TABLE backups ADD CONSTRAINT backups_target_check CHECK (target IN ('local', 'minio', 's3'));
ALTER TABLE backups ADD CONSTRAINT backups_restore_status_check CHECK (restore_status IS NULL OR restore_status IN ('untested', 'testing', 'pass', 'fail'));
CREATE UNIQUE INDEX backups_id_team_key ON backups (id, team_id);
CREATE INDEX backups_service_idx ON backups (data_service_id, created_at);
CREATE INDEX backups_schedule_idx ON backups (schedule_id, created_at);
